#include <bits/stdc++.h>
using namespace std;
int main() { int n, m; cin >> n >> m; vector<array<long long,3>> e(m); for (auto& [a, b, w] : e) cin >> a >> b >> w; int u; cin >> u; vector<long long> d(n + 1, LLONG_MAX / 4); d[u] = 0; for (int it = 0; it < n; it++) for (auto [a, b, w] : e) { d[b] = min(d[b], d[a] + w); d[a] = min(d[a], d[b] + w); } long long best = LLONG_MAX; int bm = -1; for (int mask = 0; mask < (1 << m); mask++) { if (__builtin_popcount(mask) != n - 1) continue; vector<long long> t(n + 1, LLONG_MAX / 4); t[u] = 0; for (int it = 0; it < n; it++) for (int i = 0; i < m; i++) if (mask >> i & 1) { auto [a, b, w] = e[i]; t[b] = min(t[b], t[a] + w); t[a] = min(t[a], t[b] + w); } if (t != d) continue; long long s = 0; for (int i = 0; i < m; i++) if (mask >> i & 1) s += e[i][2]; if (s < best) best = s, bm = mask; } cout << best << "\n"; for (int i = 0; i < m; i++) if (bm >> i & 1) cout << i + 1 << ' '; cout << "\n"; }
